// src/firebase/traced-firebase.js
// Optimized version of traced-firebase.js with conditional tracing based on environment

import { initializeApp } from "firebase/app";
import { getFirestore } from "firebase/firestore";
import { getAuth, GoogleAuthProvider } from "firebase/auth";
import { getStorage } from "firebase/storage"; 
import { getDatabase } from "firebase/database";
import { getAnalytics } from "firebase/analytics";

// Import optimized tracing utilities
import {
  optimizedRef as ref,
  optimizedOnValue as onValue,
  optimizedSet as set,
  optimizedUpdate as update,
  optimizedRemove as remove,
  optimizedPush as push,
  optimizedGet as get,
  optimizedDoc as doc,
  optimizedGetDoc as getDoc,
  optimizedSetDoc as setDoc,
  optimizedUpdateDoc as updateDoc,
  optimizedDeleteDoc as deleteDoc,
  optimizedCollection as collection,
  optimizedQuery as query,
  optimizedGetDocs as getDocs,
  getTracingInfo,
  isTracingEnabled
} from '../utils/firebase-trace-optimizer';

// Import original Firebase operations for query constraints
import {
  where,
  orderBy,
  limit,
  startAfter,
  endAt,
  startAt,
  endBefore
} from 'firebase/firestore';

import {
  orderByChild,
  orderByKey,
  orderByValue,
  limitToFirst,
  limitToLast,
  equalTo
} from 'firebase/database';

// Announce tracing status
if (isTracingEnabled()) {
  console.log('%c🔍 Firebase Path Tracer Enabled', 'color: green; font-weight: bold; font-size: 14px');
} else {
  console.log('%c🚀 Using Optimized Firebase (Tracing Disabled)', 'color: blue; font-weight: bold; font-size: 14px');
}

// Import app from firebase.js - we don't want to initialize it again
import { app } from '../firebase';

// Initialize services - or use the ones from firebase.js
import { db as firestoreDb, rtdb as realtimeDb } from '../firebase';

// Initialize analytics only in browser environment
let analytics;
if (typeof window !== 'undefined') {
  analytics = getAnalytics(app);
}

// Export the app and services
export { 
  app, 
  firestoreDb as db, 
  realtimeDb as rtdb, 
  analytics
};

// Export all the traced operations
export {
  // Optimized database operations  
  ref,
  onValue,
  set, 
  update,
  remove,
  push,
  get,
  
  // Optimized firestore operations
  doc,
  getDoc,
  setDoc,
  updateDoc,
  deleteDoc,
  collection,
  query,
  getDocs,
  
  // Original Firebase query constraints (no need to trace these)
  where,
  orderBy,
  limit,
  startAfter,
  endAt,
  startAt,
  endBefore,
  
  // Original realtime database query helpers
  orderByChild,
  orderByKey,
  orderByValue,
  limitToFirst,
  limitToLast,
  equalTo,
  
  // Tracing utilities
  getTracingInfo,
  isTracingEnabled
};